insert into public.app_content (content_key, version, payload, published)
values ('game.base', 1, $content${"schema_version":1,"mode":"base","title":"Мамчкин и Папчкин — Основной релиз","card_groups":{"c":[{"id":"challenge-01","number":1,"deck":"challenge","title":"Зеркало","description":"Имитируй мимику, движения или звуки ребёнка 60 секунд. Бонус — улыбка.","difficulty":"Лёгкая","timerSeconds":60},{"id":"challenge-02","number":2,"deck":"challenge","title":"Ассистент Босса","description":"Предложи открытую ладонь и жди 30 секунд; не хватай и не направляй руку.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-03","number":3,"deck":"challenge","title":"Детская дискотека","description":"Мягко танцуй 30 секунд. Бонус — ребёнок наблюдает или двигается.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-04","number":4,"deck":"challenge","title":"Вызов улыбки","description":"Попробуй вызвать улыбку голосом и мимикой за 60 секунд, без игрушек.","difficulty":"Лёгкая","timerSeconds":60},{"id":"challenge-05","number":5,"deck":"challenge","title":"Повторяшка","description":"Трижды повтори звук ребёнка. Бонус — ответный звук.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-06","number":6,"deck":"challenge","title":"Мягкий шаг","description":"Пройди на цыпочках 5 шагов и замри в смешной позе на 10 секунд.","difficulty":"Лёгкая","timerSeconds":15},{"id":"challenge-07","number":7,"deck":"challenge","title":"Контакт взглядом","description":"Привлеки внимание улыбкой; интерес суммарно 30 секунд. Не принуждай к зрительному контакту.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-08","number":8,"deck":"challenge","title":"Башенка","description":"Построй из мягких кубиков башню минимум из 3 кубиков. Малыш может её «разрушить» — это бонус.","difficulty":"Лёгкая","timerSeconds":40},{"id":"challenge-09","number":9,"deck":"challenge","title":"Гримасы","description":"Покажи 3 смешные гримасы по 5 секунд.","difficulty":"Лёгкая","timerSeconds":15},{"id":"challenge-10","number":10,"deck":"challenge","title":"Мягкое шуршание","description":"Используй безопасную шуршащую игрушку; не используй громкие/опасные предметы.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-11","number":11,"deck":"challenge","title":"Выбор Босса","description":"Предложи 2 знакомые игрушки и предскажи, какая заинтересует ребёнка.","difficulty":"Средняя","timerSeconds":30},{"id":"challenge-12","number":12,"deck":"challenge","title":"Повелитель взгляда","description":"Медленно двигай игрушку; ребёнок следит суммарно ≥20 секунд за 45 секунд.","difficulty":"Средняя","timerSeconds":45},{"id":"challenge-13","number":13,"deck":"challenge","title":"Интуиция родителя","description":"За 60 секунд предскажи следующее действие ребёнка.","difficulty":"Средняя","timerSeconds":60},{"id":"challenge-14","number":14,"deck":"challenge","title":"Ку-ку с перехватом","description":"Мягко появись слева/справа и добейся 3 проявлений интереса.","difficulty":"Средняя","timerSeconds":45},{"id":"challenge-15","number":15,"deck":"challenge","title":"Танец ладошек","description":"Мягкая игра ладонями с песенкой, только если ребёнку комфортно.","difficulty":"Средняя","timerSeconds":30},{"id":"challenge-16","number":16,"deck":"challenge","title":"Сказка про Босса","description":"Расскажи мини-сказку, где малыш — главный герой, в три части: начало, приключение, конец.","difficulty":"Средняя","timerSeconds":45},{"id":"challenge-17","number":17,"deck":"challenge","title":"Назови всё вокруг","description":"Назови малышу 10 предметов в комнате, показывая на каждый.","difficulty":"Лёгкая","timerSeconds":30},{"id":"challenge-18","number":18,"deck":"challenge","title":"Поисковик","description":"Спокойно позови слева и справа вне поля зрения; не кричи.","difficulty":"Средняя","timerSeconds":30},{"id":"challenge-19","number":19,"deck":"challenge","title":"Фокус с исчезновением","description":"Накрой игрушку лёгкой тканью и открой. Лицо ребёнка не закрывай.","difficulty":"Средняя","timerSeconds":30},{"id":"challenge-20","number":20,"deck":"challenge","title":"Реклама игрушки","description":"За 30 секунд представь игрушку как невероятное изобретение; закончи, не рассмеявшись.","difficulty":"Сложная","timerSeconds":30},{"id":"challenge-21","number":21,"deck":"challenge","title":"Евровидение для Босса","description":"Спой колыбельную 30 секунд. Микрофон не записывает звук; результат выбирается вручную.","difficulty":"Сложная","timerSeconds":30},{"id":"challenge-22","number":22,"deck":"challenge","title":"Диктор Босса","description":"Комментируй всё, что делает малыш, как спортивный репортёр.","difficulty":"Средняя","timerSeconds":45},{"id":"challenge-23","number":23,"deck":"challenge","title":"Портрет Босса","description":"Нарисуй портрет Босса на бумаге за 60 секунд. Фотографии и подсказки запрещены!","difficulty":"Средняя","timerSeconds":60},{"id":"challenge-24","number":24,"deck":"challenge","title":"Тихий оркестр","description":"Сыграй три разных мягких ритма: ладонями по подушке, по мягкой игрушке и по сложенной ткани. Звук тихий.","difficulty":"Средняя","timerSeconds":40},{"id":"challenge-25","number":25,"deck":"challenge","title":"Паспорт Босса","description":"Без подсказок назови вслух 5 фактов о малыше: любимая игрушка, песенка, что смешит, как засыпает, как радуется.","difficulty":"Сложная","timerSeconds":60},{"id":"challenge-26","number":26,"deck":"challenge","title":"Тактильное путешествие","description":"Проведи по ладошке или ножке малыша тремя безопасными фактурами.","difficulty":"Средняя","timerSeconds":45},{"id":"challenge-27","number":27,"deck":"challenge","title":"Двойной фокус","description":"За 45 секунд заинтересуй ребёнка двумя знакомыми игрушками.","difficulty":"Сложная","timerSeconds":45},{"id":"challenge-28","number":28,"deck":"challenge","title":"Смешинка","description":"Попробуй вызвать смех или радостный визг за 60 секунд; не щекочи и не пугай.","difficulty":"Средняя","timerSeconds":60},{"id":"challenge-29","number":29,"deck":"challenge","title":"Угадай настроение","description":"Определи по сигналам, заинтересован ли ребёнок, устал или хочет паузу. Это не диагностика.","difficulty":"Сложная","timerSeconds":30},{"id":"challenge-30","number":30,"deck":"challenge","title":"Мягкая посадка","description":"Положи мягкую игрушку рядом с рукой ребёнка; жди 40 секунд. Ребёнок бодрствует и под присмотром.","difficulty":"Средняя","timerSeconds":40}],"k":[{"id":"care-31","number":31,"deck":"care","title":"Запасной комплект","description":"Подготовь чистую одежду; если готова — проверь запас в сумке.","tag":"Подготовка"},{"id":"care-32","number":32,"deck":"care","title":"Ночной концерт","description":"Возьми следующую согласованную ночную задачу. Срочный уход не откладывай.","tag":"Ночной уход"},{"id":"care-33","number":33,"deck":"care","title":"Внезапные газики","description":"Мягкие движения ножками «велосипед» только если уместно; остановись при дискомфорте.","tag":"Забота"},{"id":"care-34","number":34,"deck":"care","title":"Утренняя побудка","description":"Встань на 30 минут раньше партнёра, если позволяет режим семьи.","tag":"Забота"},{"id":"care-35","number":35,"deck":"care","title":"Молчаливый режим","description":"В следующем игровом раунде общайся только жестами; только во время игры.","tag":"Игровое"},{"id":"care-36","number":36,"deck":"care","title":"Кофейная доставка","description":"Приготовь партнёру горячий напиток и держи его вдали от ребёнка.","tag":"Быт"},{"id":"care-37","number":37,"deck":"care","title":"Налог на игрушки","description":"Передай партнёру 1 очко; если очков нет — долг не создаётся.","tag":"Игровое"},{"id":"care-38","number":38,"deck":"care","title":"Колыбельная нон-стоп","description":"Пой/успокаивай 5–10 минут, пока партнёр отдыхает; не требуется добиться сна.","tag":"Забота"},{"id":"care-39","number":39,"deck":"care","title":"Вечерняя мойка посуды","description":"Вымой посуду после ужина; если уже вымыта — небольшая кухонная задача.","tag":"Быт"},{"id":"care-40","number":40,"deck":"care","title":"Ревизия запасов","description":"Проверь подгузники/салфетки и пополни запас за 24 часа.","tag":"Подготовка"},{"id":"care-41","number":41,"deck":"care","title":"Смена подгузника 3/3","description":"Возьми следующие 3 смены, которые обычно делятся; не откладывай необходимую смену.","tag":"Забота"},{"id":"care-42","number":42,"deck":"care","title":"Внеплановая влажная уборка","description":"Убери одну небольшую игровую зону.","tag":"Быт"},{"id":"care-43","number":43,"deck":"care","title":"Уборка после каши","description":"Убери стульчик и поверхность после еды.","tag":"Быт"},{"id":"care-44","number":44,"deck":"care","title":"Ночная доставка пледа","description":"По просьбе принеси партнёру плед, не мешая отдыху.","tag":"Ночной уход"},{"id":"care-45","number":45,"deck":"care","title":"Стирка пелёнок","description":"Запусти стирку детских вещей сегодня.","tag":"Быт"},{"id":"care-46","number":46,"deck":"care","title":"Гладильный босс","description":"Погладь 3 нужные вещи; иначе подготовь 3 комплекта на завтра.","tag":"Быт"},{"id":"care-47","number":47,"deck":"care","title":"Режим «Попугай»","description":"Два игровых раунда говори цитатами из мультфильмов; не во время ухода.","tag":"Игровое"},{"id":"care-48","number":48,"deck":"care","title":"Игрушечный апокалипсис","description":"Убери игрушки в одной игровой зоне.","tag":"Быт"},{"id":"care-49","number":49,"deck":"care","title":"Вечерний отбой","description":"Выполни привычный ритуал укладывания; успех — ритуал, не обязательно сон.","tag":"Забота"},{"id":"care-50","number":50,"deck":"care","title":"Потерянный соска-сберегатель","description":"Следующая награда теряет один выбранный эффект.","tag":"Особое"}],"r":[{"id":"reward-51","number":51,"deck":"reward","title":"Ночной иммунитет","description":"Отмени билет с ночной обязанностью. Только метка «Ночной уход».","effectType":"ability"},{"id":"reward-52","number":52,"deck":"reward","title":"Час тишины","description":"Час без обычных бытовых задач по договорённости; ребёнок в приоритете.","effectType":"ticket"},{"id":"reward-53","number":53,"deck":"reward","title":"Официальный кофе-брейк","description":"Партнёр готовит горячий напиток.","effectType":"ticket"},{"id":"reward-54","number":54,"deck":"reward","title":"Заказ ужина","description":"Выбери ужин в рамках бюджета и пищевых ограничений.","effectType":"ticket"},{"id":"reward-55","number":55,"deck":"reward","title":"Массаж плеч","description":"Массаж плеч/шеи до 15 минут, по согласию.","effectType":"ticket"},{"id":"reward-56","number":56,"deck":"reward","title":"Властелин пульта","description":"Выбери фильм, сериал или музыку на вечер.","effectType":"ticket"},{"id":"reward-57","number":57,"deck":"reward","title":"Массаж ног","description":"Массаж ног до 15 минут, по согласию.","effectType":"ticket"},{"id":"reward-58","number":58,"deck":"reward","title":"Освобождение от посуды","description":"Партнёр моет посуду после одного ужина.","effectType":"ticket"},{"id":"reward-59","number":59,"deck":"reward","title":"Купон на обнимашки","description":"Можно попросить объятие; требуется согласие.","effectType":"ticket"},{"id":"reward-60","number":60,"deck":"reward","title":"Мягкий иммунитет","description":"Отмени одну будущую карту заботы; не отменяет безопасность.","effectType":"ability"},{"id":"reward-61","number":61,"deck":"reward","title":"Тихий час для двоих","description":"10 минут совместного отдыха; уход за ребёнком в приоритете.","effectType":"ticket"},{"id":"reward-62","number":62,"deck":"reward","title":"Шоколадный бонус","description":"Любимая сладость/перекус с учётом ограничений.","effectType":"ticket"},{"id":"reward-63","number":63,"deck":"reward","title":"Королевский завтрак","description":"Завтрак в ближайшие выходные с учётом ограничений.","effectType":"ticket"},{"id":"reward-64","number":64,"deck":"reward","title":"Право на тишину","description":"Партнёр берёт согласованные задачи на 30 минут для твоего отдыха.","effectType":"ticket"},{"id":"reward-65","number":65,"deck":"reward","title":"Два часа свободы","description":"2 часа личного времени в течение 7 дней по договорённости.","effectType":"ticket"},{"id":"reward-66","number":66,"deck":"reward","title":"Слуга Босса — наоборот","description":"Партнёр выполняет одну разумную бытовую задачу.","effectType":"ticket"},{"id":"reward-67","number":67,"deck":"reward","title":"Золотое вето","description":"Отмени подходящий активный билет заботы/штрафа; срочный уход не отменяется.","effectType":"ability"},{"id":"reward-68","number":68,"deck":"reward","title":"Плюс 2 очка","description":"Начисли +2 очка один раз.","effectType":"instant"},{"id":"reward-69","number":69,"deck":"reward","title":"Выбор досуга","description":"Выбери вечерний досуг после первоочередных задач.","effectType":"ticket"},{"id":"reward-70","number":70,"deck":"reward","title":"Супер-Родитель","description":"Вытяни 2 награды, выбери одну, вторую верни; без цепочек.","effectType":"special"}]}}$content$, false)
on conflict (content_key, version) do nothing;
